video.script:
(function(){
  try {
    var doc = document;
    // A) 播放器页已初始化：video 元素直链（blob: 是 hls.js MSE 包装，跳过）
    var v = doc.querySelector('video source[src], video[src]');
    if (v) {
      var s = (v.getAttribute && v.getAttribute('src')) || '';
      if (/^https?:\/\//i.test(s)) return s;
    }
    // B) 播放器页：MuiPlayer/hls.js 发起的媒体请求在 performance 资源表里
    try {
      var res = window.performance && window.performance.getEntriesByType ? window.performance.getEntriesByType('resource') : [];
      for (var i = res.length - 1; i >= 0; i--) {
        var n = res[i].name || '';
        if (/^https?:\/\//i.test(n) && /\.(m3u8|mp4|mknvideo)(\?|$)/i.test(n)) return n;
      }
    } catch (e2) {}
    // C) 播放页：player_aaaa(encrypt=2) 令牌（brace 平衡截取，不依赖行尾分号）
    var html = doc.documentElement.outerHTML;
    var idx = html.indexOf('player_aaaa');
    if (idx >= 0) {
      var start = html.indexOf('{', idx);
      if (start >= 0) {
        var depth = 0, end = -1;
        for (var j = start; j < html.length && j < start + 20000; j++) {
          var ch = html.charAt(j);
          if (ch === '{') depth++;
          else if (ch === '}') { depth--; if (depth === 0) { end = j + 1; break; } }
        }
        if (end > start) {
          var cfg = {};
          try { cfg = new Function('return (' + html.substring(start, end) + ')')(); } catch (e3) { cfg = {}; }
          if (cfg && cfg.url && cfg.from) {
            // parse 映射来自站点 /static/js/playerconfig.js + /static/player/parse.js
            var parseMap = {
              '2_': 'https://play.mknacg.top:8585/cloudplay/?url=',
              '5_': 'https://play.mknacg.top:8585/cloudplay/yp2.php?url=',
              '6_': 'https://play.mknacg.top:8585/cloudplay/yp3.php?url=',
              '4_': 'https://play.mknacg.top:8585/cloudplay/ccxl.php?url=',
              '3_': 'https://play.mknacg.top:8585/muiplayer/?url='
            };
            var parse = parseMap[cfg.from];
            if (parse) return 'webview:' + parse + cfg.url;
          }
        }
      }
    }
    // D) 兜底：cloudplay/muiplayer iframe → 引擎跳转该页重跑本脚本
    var f = doc.querySelector('iframe#videoiframe, iframe[src*="cloudplay"], iframe[src*="muiplayer"]');
    if (f) {
      var fs = f.getAttribute('src') || '';
      if (/^https?:\/\//i.test(fs)) return 'webview:' + fs;
    }
    return '';
  } catch (e) { return ''; }
})();
